package pt.qpetiscos.agenda;
import android.app.*;import android.appwidget.*;import android.app.job.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.widget.RemoteViews;import org.json.*;import java.net.*;import java.io.*;import java.time.*;import java.util.concurrent.*;
public class WidgetAgenda extends AppWidgetProvider {
 static final String BASE="https://kyzwmaydwokbfmiskhcg.supabase.co/rest/v1/events", KEY="sb_publishable_Ko1iv1CWVi693R9_-xwNvg_5auNwzAy";
 static final ExecutorService EXEC=Executors.newSingleThreadExecutor();static void runAsync(Runnable r){EXEC.execute(r);} static void refreshAll(Context c){Context a=c.getApplicationContext();runAsync(()->updateAll(a));}
 static void schedule(Context c){try{JobScheduler js=c.getSystemService(JobScheduler.class);if(js!=null&&js.getPendingJob(410)==null)js.schedule(new JobInfo.Builder(410,new ComponentName(c,WidgetJob.class)).setPeriodic(15*60*1000).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).build());}catch(RuntimeException e){android.util.Log.e("QPWidget","Falha ao agendar atualização dos widgets",e);}}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){schedule(c);refreshAll(c);}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);String act=i.getAction();if(act==null||!act.startsWith("qp."))return;int wid=i.getIntExtra("wid",-1);String event=i.getStringExtra("event");android.content.SharedPreferences prefs=c.getSharedPreferences("widget_state",0);if(wid<0)return; if("qp.day".equals(act))prefs.edit().putString("date"+wid,event).apply();if("qp.filter".equals(act))prefs.edit().putString("filter"+wid,event).apply();if("qp.expand".equals(act))prefs.edit().putBoolean("expanded"+wid+event,!prefs.getBoolean("expanded"+wid+event,false)).apply();PendingResult pending=goAsync();Context a=c.getApplicationContext();runAsync(()->{try{if("qp.toggle".equals(act)||"qp.delete".equals(act)){JSONObject ss=session(a);if(event!=null&&event.matches("[a-fA-F0-9-]{36}")){JSONObject body=new JSONObject().put("updated_by",ss.getString("device"));if("qp.delete".equals(act))body.put("deleted_at",java.time.Instant.now().toString());else body.put("completed",i.getBooleanExtra("done",false));request(ss,"PATCH","?id=eq."+event+"&user_id=eq."+ss.getString("uid")+"&deleted_at=is.null",body);}}}catch(Exception e){android.util.Log.w("QPWidget","Alteração falhou",e);new android.os.Handler(android.os.Looper.getMainLooper()).post(()->android.widget.Toast.makeText(a,"Não foi possível guardar a alteração",android.widget.Toast.LENGTH_SHORT).show());}finally{try{updateAll(a);}finally{pending.finish();}}});}
 static JSONObject session(Context c)throws Exception{JSONObject s=new JSONObject(c.getSharedPreferences("widget_session",0).getString("session",""));if(s.isNull("device")||s.optString("device").isEmpty())throw new IOException("Abre a agenda e inicia sessão");return s;}
 static String request(JSONObject s,String method,String query,JSONObject body)throws Exception{HttpURLConnection h=(HttpURLConnection)new URL(BASE+query).openConnection();h.setConnectTimeout(5000);h.setReadTimeout(5000);h.setRequestMethod(method);h.setRequestProperty("apikey",KEY);h.setRequestProperty("Authorization","Bearer "+s.getString("token"));try{if(body!=null){h.setDoOutput(true);h.setRequestProperty("Content-Type","application/json");try(OutputStream o=h.getOutputStream()){o.write(body.toString().getBytes("UTF-8"));}}int code=h.getResponseCode();if(code==401||code==403)throw new IOException("Abre a agenda para renovar a sessão");if(code<200||code>=300)throw new IOException("Erro de sincronização");try(InputStream in=h.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}finally{h.disconnect();}}
 static LocalDate date(Context c,int id){try{return LocalDate.parse(c.getSharedPreferences("widget_state",0).getString("date"+id,""));}catch(Exception e){return LocalDate.now(ZoneId.of("Europe/Lisbon"));}}
 static LocalDate monday(LocalDate d){return d.minusDays(d.getDayOfWeek().getValue()-1);}
 static void updateAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);for(Class<?> t:new Class<?>[]{FullWidget.class,TakeawayWidget.class})for(int id:m.getAppWidgetIds(new ComponentName(c,t))){JSONArray rows=new JSONArray();String status="";try{JSONObject ss=session(c);LocalDate mon=monday(date(c,id));rows=new JSONArray(request(ss,"GET","?select=id,type,name,event_date,event_time,notes,completed&user_id=eq."+ss.getString("uid")+"&event_date=gte."+mon+"&event_date=lte."+mon.plusDays(6)+"&deleted_at=is.null&order=event_time.asc,id.asc",null));}catch(Exception e){status=e instanceof JSONException?"Abre a agenda e inicia sessão":e.getMessage();}c.getSharedPreferences("widget_rows",0).edit().putString("rows"+id,rows.toString()).apply();render(c,m,t,id,rows,status);}}
 static PendingIntent action(Context c,Class<?> t,int id,String action,String event,boolean done){Intent i=new Intent(c,t).setAction(action).setData(Uri.parse("qp://widget/"+id+"/"+action+"/"+event)).putExtra("wid",id).putExtra("event",event).putExtra("done",done);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static int theme(Context c,int id){return Math.max(0,Math.min(2,c.getSharedPreferences("widget_theme",0).getInt("theme"+id,0)));}
 static int fg(int t){return t==0?0xff402817:Color.WHITE;}static int card(int t){return new int[]{R.drawable.widget_card0,R.drawable.widget_card1,R.drawable.widget_card2}[t];}
 static String filter(Context c,int id,boolean take){return take?"takeaway":c.getSharedPreferences("widget_state",0).getString("filter"+id,"all");}
 static PendingIntent open(Context c,int id,String query){Intent i=new Intent(c,MainActivity.class).setData(Uri.parse("qp://open/"+id+"/"+Uri.encode(query))).putExtra("qp_query",query).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);return PendingIntent.getActivity(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void render(Context c,AppWidgetManager m,Class<?> t,int id,JSONArray rows,String status){int theme=theme(c,id),fg=fg(theme);boolean take=t==TakeawayWidget.class;LocalDate d=date(c,id),mon=monday(d);RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_agenda);v.setInt(R.id.widget_root,"setBackgroundResource",new int[]{R.drawable.widget_bg0,R.drawable.widget_bg1,R.drawable.widget_bg2}[theme]);for(int x:new int[]{R.id.widget_title,R.id.widget_status,R.id.widget_refresh,R.id.prev,R.id.next,R.id.date_title,R.id.add,R.id.widget_empty})v.setTextColor(x,fg);v.setTextViewText(R.id.widget_title,take?"Takeaway":"Agenda QPetiscos");v.setTextViewText(R.id.date_title,d.format(java.time.format.DateTimeFormatter.ofPattern("EEEE, dd/MM",new java.util.Locale("pt","PT"))));v.setOnClickPendingIntent(R.id.prev,action(c,t,id,"qp.day",d.minusWeeks(1).toString(),false));v.setOnClickPendingIntent(R.id.next,action(c,t,id,"qp.day",d.plusWeeks(1).toString(),false));int[] days={R.id.day0,R.id.day1,R.id.day2,R.id.day3,R.id.day4,R.id.day5,R.id.day6};String[] names={"Seg","Ter","Qua","Qui","Sex","Sáb","Dom"};int reserve=0,orders=0;for(int n=0;n<7;n++){LocalDate day=mon.plusDays(n);int count=0;for(int k=0;k<rows.length();k++){JSONObject e=rows.optJSONObject(k);if(e==null||!day.toString().equals(e.optString("event_date")))continue;boolean res="reserva".equals(e.optString("type"));if(!take||!res)count++;if(day.equals(d)){if(res)reserve++;else orders++;}}v.setTextViewText(days[n],names[n]+"\n"+day.getDayOfMonth()+"\n"+(count==0?" ":count));v.setInt(days[n],"setBackgroundResource",day.equals(d)?(theme==0?R.drawable.widget_bg1:R.drawable.widget_bg0):card(theme));v.setTextColor(days[n],day.equals(d)?(theme==0?Color.WHITE:0xff402817):fg);v.setOnClickPendingIntent(days[n],action(c,t,id,"qp.day",day.toString(),false));}int[] fs={R.id.filter0,R.id.filter1,R.id.filter2};String[] keys={"all","reserva","takeaway"},labels={(reserve+orders)+" Total",reserve+" Res.",orders+" Takeaway"};for(int n=0;n<3;n++){v.setViewVisibility(fs[n],take&&n!=2?android.view.View.GONE:android.view.View.VISIBLE);v.setTextViewText(fs[n],labels[n]);boolean active=keys[n].equals(filter(c,id,take));v.setTextColor(fs[n],active?(theme==0?Color.WHITE:0xff402817):fg);v.setInt(fs[n],"setBackgroundResource",active?(theme==0?R.drawable.widget_bg1:R.drawable.widget_bg0):card(theme));v.setOnClickPendingIntent(fs[n],action(c,t,id,"qp.filter",keys[n],false));}v.setTextViewText(R.id.widget_status,status);v.setViewVisibility(R.id.widget_status,status.isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);v.setOnClickPendingIntent(R.id.widget_refresh,action(c,t,id,"qp.refresh","",false));v.setOnClickPendingIntent(R.id.widget_title,open(c,id,"qp=day&date="+d));v.setOnClickPendingIntent(R.id.add,open(c,id,"qp=add&date="+d+"&type="+(take?"takeaway":"all")));Intent adapter=new Intent(c,WidgetRows.class).putExtra("wid",id).putExtra("take",take).setData(Uri.parse("qp://rows/"+id));if(android.os.Build.VERSION.SDK_INT>=31){WidgetRows.Factory factory=new WidgetRows.Factory(c,id,take);factory.onDataSetChanged();RemoteViews.RemoteCollectionItems.Builder items=new RemoteViews.RemoteCollectionItems.Builder().setHasStableIds(true).setViewTypeCount(1);for(int n=0;n<factory.getCount();n++)items.addItem(factory.getItemId(n),factory.getViewAt(n));v.setRemoteAdapter(R.id.widget_rows,items.build());}else{adapter.setData(Uri.parse("qp://rows/"+id+"/"+d+"/"+filter(c,id,take)));v.setRemoteAdapter(R.id.widget_rows,adapter);}v.setEmptyView(R.id.widget_rows,R.id.widget_empty);Intent template=new Intent(c,WidgetClick.class).putExtra("wid",id).putExtra("take",take).setData(Uri.parse("qp://click/"+id));v.setPendingIntentTemplate(R.id.widget_rows,PendingIntent.getBroadcast(c,id,template,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE));m.updateAppWidget(id,v);if(android.os.Build.VERSION.SDK_INT<31)m.notifyAppWidgetViewDataChanged(id,R.id.widget_rows);}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){refreshAll(c);}
}
